import type { Column, Typed } from '../Column'

type HtmlColumnType<Type extends string = string, Default extends Type = Type> = Column<Type, Default>

/**
 * A Column for an HTML type field.
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @param config - an object that can include all base `Column` properties
 *   * **maxLength**? - maximum number of characters allowed in this field
 *
 * @example
 * ```typescript
 * const description = HTMLColumn({
 *     label: 'Description',
 *     default: html('<h2>Title</h2><p>Content</p>'),
 * })
 * ```
 */
export function HtmlColumn<
    const Type extends string = string,
    const Default extends Type = Type,
    const C extends HtmlColumnType<Type, Default> = HtmlColumnType<Type, Default>,
>(config: C & HtmlColumnType<Type, Default>) {
    return config as Typed<Type, C>
}
